 repo,pin=pins[tag];b=get(f'https://api.github.com/repos/{repo}/git/trees/{pin}?recursive=1');t=json.loads(b);assert not t.get('truncated');(base/f'{tag}-tree.json').write_bytes(b);return tag,{x['path']:x['sha'] for x in t['tree'] if x['type']=='blob'}
