def fetch(j):
 tag,path=j;repo,pin=pins[tag];u=f'https://raw.githubusercontent.com/{repo}/{pin}/{path}';b=get(u);f=base/'sources'/tag/path;f.parent.mkdir(parents=True,exist_ok=True);f.write_bytes(b);blob=hashlib.sha1(f'blob {len(b)}\0'.encode()+b).hexdigest();assert blob==trees[tag][path];return {'source':tag,'repo':repo,'pin':pin,'path':path,'url':u,'local':str(f),'bytes':len(b),'sha256':hashlib.sha256(b).hexdigest(),'git_blob':blob,'tree_blob':trees[tag][path],'git_blob_verified':True}
